<script lang="ts">import { Link, navigate } from 'svelte-routing'; import { signup } from '../auth/auth'; let name = $state(''); let email = $state(''); let password = $state(''); let error = $state(''); let attempted = $state(false); let isValid = $derived(Boolean(name.trim()) && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) && password.length >= 6); async function submit(event: SubmitEvent): Promise<void> { event.preventDefault(); attempted = true; if (!isValid) return; if (await signup(name, email, password)) navigate('/dashboard'); else error = 'An account already uses that email.' }</script><main class="grid min-h-screen place-items-center bg-surface p-5"><form onsubmit={submit} class="w-full max-w-md rounded-panel bg-card p-8 shadow-sm ring-1 ring-line"><div class="text-center"><p class="text-2xl font-bold text-navy">Shoply</p><h1 class="mt-6 text-2xl font-bold text-navy">Create your account</h1><p class="mt-2 text-muted">Save favorites and make checkout easy.</p></div><label class="mt-7 block text-sm font-semibold text-navy">Name<input bind:value={name} class="mt-2 w-full rounded-lg border border-line px-3 py-3 font-normal outline-primary"/></label><label class="mt-4 block text-sm font-semibold text-navy">Email<input bind:value={email} type="email" class="mt-2 w-full rounded-lg border border-line px-3 py-3 font-normal outline-primary"/></label><label class="mt-4 block text-sm font-semibold text-navy">Password<input bind:value={password} type="password" class="mt-2 w-full rounded-lg border border-line px-3 py-3 font-normal outline-primary"/></label>{#if attempted && !isValid}<p class="mt-3 text-sm text-danger">Enter your name, a valid email, and a password of at least 6 characters.</p>{/if}{#if error}<p class="mt-3 text-sm text-danger">{error}</p>{/if}<button disabled={!isValid} class="mt-6 w-full rounded-xl bg-primary px-4 py-3 font-semibold text-white disabled:opacity-50">Create account</button><p class="mt-5 text-center text-sm text-muted">Already have an account? <Link to="/login" class="font-semibold text-primary">Sign in</Link></p></form></main>
